import java.util.*;

public class Main {
    public static void main(String[] args) {
        // 준비된 상품 목록을 같은 규칙으로 집계하세요.
        String[] items = {"book", "pen", "book"};
        Map<String, Integer> counts = new HashMap<>();
        for (String item : items) {
            // 이전에 저장된 수와 새 상품의 기본값을 생각하세요.
            counts.put(item, 1);
        }
        // 출력 순서를 명시해 내용으로 결과를 비교해요.
        System.out.println(new TreeMap<>(counts));
    }
}

tasks.solution:
import java.util.*;


public class Main {
    public static void main(String[] args) {
        // 준비된 상품 목록을 같은 규칙으로 집계하세요.
        String[] items = {"book", "pen", "book"};
        Map<String, Integer> counts = new HashMap<>();
        for (String item : items) {
            // 이전에 저장된 수와 새 상품의 기본값을 생각하세요.
            counts.put(item, counts.getOrDefault(item, 0) + 1);
        }
        // 출력 순서를 명시해 내용으로 결과를 비교해요.
        System.out.println(new TreeMap<>(counts));
    }
}
